CREATE TABLE IF NOT EXISTS users(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS documents(id BIGINT PRIMARY KEY AUTO_INCREMENT,owner_id BIGINT NOT NULL,filename VARCHAR(255) NOT NULL,path VARCHAR(600) NOT NULL,mime_type VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL,chunk_count INT DEFAULT 0,error TEXT,created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3),INDEX(owner_id),FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sessions(id BIGINT PRIMARY KEY AUTO_INCREMENT,owner_id BIGINT NOT NULL,title VARCHAR(100) NOT NULL,created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS tasks(id BIGINT PRIMARY KEY AUTO_INCREMENT,owner_id BIGINT NOT NULL,session_id BIGINT NOT NULL,instruction TEXT NOT NULL,document_ids JSON NOT NULL,idempotency_key VARCHAR(80) NOT NULL,request_hash CHAR(64) NOT NULL,status VARCHAR(20) NOT NULL,result LONGTEXT,error TEXT,review_status VARCHAR(20) DEFAULT 'PENDING',version INT NOT NULL DEFAULT 0,created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3),updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE(owner_id,idempotency_key),FOREIGN KEY(owner_id) REFERENCES users(id),FOREIGN KEY(session_id) REFERENCES sessions(id));
CREATE TABLE IF NOT EXISTS agent_runs(id VARCHAR(36) PRIMARY KEY,task_id BIGINT NOT NULL,parent_id VARCHAR(36),name VARCHAR(100) NOT NULL,prompt TEXT NOT NULL,status VARCHAR(20) NOT NULL,result LONGTEXT,steps INT DEFAULT 0,prompt_tokens INT DEFAULT 0,completion_tokens INT DEFAULT 0,created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(task_id) REFERENCES tasks(id));
CREATE TABLE IF NOT EXISTS tool_calls(id VARCHAR(100) PRIMARY KEY,task_id BIGINT NOT NULL,agent_id VARCHAR(36) NOT NULL,name VARCHAR(80) NOT NULL,arguments LONGTEXT NOT NULL,result LONGTEXT,status VARCHAR(20) NOT NULL,duration_ms BIGINT DEFAULT 0,created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(task_id) REFERENCES tasks(id));
CREATE TABLE IF NOT EXISTS evidence(task_id BIGINT NOT NULL,chunk_id VARCHAR(36) NOT NULL,document_id BIGINT NOT NULL,payload JSON NOT NULL,PRIMARY KEY(task_id,chunk_id),FOREIGN KEY(task_id) REFERENCES tasks(id),FOREIGN KEY(document_id) REFERENCES documents(id));
CREATE TABLE IF NOT EXISTS task_events(id BIGINT PRIMARY KEY AUTO_INCREMENT,task_id BIGINT NOT NULL,type VARCHAR(40) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3),INDEX(task_id,id),FOREIGN KEY(task_id) REFERENCES tasks(id));
CREATE TABLE IF NOT EXISTS reviews(id BIGINT PRIMARY KEY AUTO_INCREMENT,task_id BIGINT NOT NULL,owner_id BIGINT NOT NULL,decision VARCHAR(20) NOT NULL,note TEXT NOT NULL,created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(task_id) REFERENCES tasks(id),FOREIGN KEY(owner_id) REFERENCES users(id));
